    out = [row[:] for row in grid]

    # Find the centers of 3x3 motifs: a 2 surrounded by eight 3s.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    max_row_twos = max((row.count(2) for row in grid), default=0)
    max_col_twos = max(
        (sum(grid[r][c] == 2 for r in range(h)) for c in range(w)),
        default=0
    )

    # Project perpendicular to the repeated 2-lines.
    horizontal_projection = max_col_twos > max_row_twos

    for r, c in centers:
        if horizontal_projection:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            crossings = [(r, cc) for cc in range(w) if grid[r][cc] == 2]
        else:
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            crossings = [(rr, c) for rr in range(h) if grid[rr][c] == 2]

        # Mark a 3x3 halo at each crossing, keeping the crossing itself
        # and any original 3s unchanged.
        for cr, cc in crossings:
            for rr in range(max(0, cr - 1), min(h, cr + 2)):
                for ccc in range(max(0, cc - 1), min(w, cc + 2)):
                    if (rr, ccc) != (cr, cc) and out[rr][ccc] != 3:
                        out[rr][ccc] = 1

    return out
